  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080b12;
      --panel: rgba(20, 26, 41, 0.86);
      --panel-strong: #151b2c;
      --text: #eef4ff;
      --muted: #aab6c8;
      --accent: #8bd8ff;
      --accent-2: #c795ff;
      --border: rgba(255, 255, 255, 0.12);
      --shadow: rgba(0, 0, 0, 0.36);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.6;
      color: var(--text);
      background:
        radial-gradient(circle at 15% 10%, rgba(139, 216, 255, 0.22), transparent 30rem),
        radial-gradient(circle at 85% 20%, rgba(199, 149, 255, 0.16), transparent 28rem),
        linear-gradient(145deg, #080b12 0%, #101624 54%, #070911 100%);
    }

    main {
      width: min(920px, calc(100% - 32px));
      margin: 0 auto;
      padding: 72px 0;
    }

    .hero {
      margin-bottom: 34px;
      text-align: center;
    }

    .eyebrow {
      display: inline-flex;
      gap: 8px;
      align-items: center;
      margin: 0 0 14px;
      padding: 7px 12px;
      border: 1px solid var(--border);
      border-radius: 999px;
      color: var(--accent);
      background: rgba(255, 255, 255, 0.06);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.35rem, 8vw, 5rem);
      line-height: 0.95;
      letter-spacing: -0.06em;
    }

    .intro {
      max-width: 670px;
      margin: 22px auto 0;
      color: var(--muted);
      font-size: 1.08rem;
    }

    .faq {
      display: grid;
      gap: 16px;
    }

    .example {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 22px;
      background: linear-gradient(180deg, var(--panel), rgba(12, 17, 29, 0.86));
      box-shadow: 0 22px 70px var(--shadow);
      backdrop-filter: blur(18px);
      transition: border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
    }

    .example:hover {
      border-color: rgba(139, 216, 255, 0.36);
      transform: translateY(-2px);
      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.42);
    }

    .question {
      display: flex;
      width: 100%;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 24px 26px;
      border: 0;
      color: inherit;
      background: transparent;
      font: inherit;
      font-size: 1.08rem;
      font-weight: 750;
      text-align: left;
      cursor: pointer;
    }

    .question:focus-visible {
      outline: 3px solid rgba(139, 216, 255, 0.72);
      outline-offset: -6px;
    }

    .icon {
      display: grid;
      flex: 0 0 auto;
      width: 34px;
      height: 34px;
      place-items: center;
      border-radius: 50%;
      color: #07101a;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      font-size: 1.4rem;
      font-weight: 500;
      transition: transform 180ms ease;
    }

    .question[aria-expanded="true"] .icon {
      transform: rotate(45deg);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

