      grid-template-rows: 1fr;
    }

    .answer {
      min-height: 0;
      overflow: hidden;
    }

    .answer-inner {
      padding: 0 26px 26px;
      color: var(--muted);
    }

    .answer-inner p {
      margin: 0;
      padding-top: 2px;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
    }

    @media (max-width: 620px) {
      main {
        width: min(100% - 22px, 920px);
        padding: 42px 0;
      }

      .question {
        padding: 20px;
        font-size: 1rem;
      }

      .answer-inner {
        padding: 0 20px 22px;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="hero" aria-labelledby="page-title">
      <p class="eyebrow">Cat care FAQ</p>
      <h1 id="page-title">Curious about cats?</h1>
      <p class="intro">
        Quick answers to common questions about feline behavior, care, and comfort.
        Select a question to reveal the answer.
      </p>
    </section>

    <section class="faq" aria-label="Frequently asked questions about cats">
      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1">
          <span>Why do cats purr?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="answer-1">
          <div class="answer">
            <div class="answer-inner">
              <p>Cats often purr when they feel relaxed and content, but they may also purr to self-soothe when stressed, injured, or seeking comfort.</p>
            </div>
          </div>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-2">
          <span>How much sleep do cats need?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="answer-2">
          <div class="answer">
            <div class="answer-inner">
              <p>Most adult cats sleep around 12 to 16 hours per day. Kittens and senior cats can sleep even longer because growth and recovery take extra energy.</p>
            </div>
          </div>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-3">
          <span>Why does my cat knead blankets or laps?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="answer-3">
          <div class="answer">
            <div class="answer-inner">
              <p>Kneading is a comforting kitten behavior many cats keep into adulthood. It can mean your cat feels safe, affectionate, or ready to settle in for a nap.</p>
            </div>
          </div>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-4">
          <span>Do indoor cats need enrichment?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="answer-4">
          <div class="answer">
            <div class="answer-inner">
              <p>Yes. Toys, scratching posts, climbing spots, puzzle feeders, window perches, and regular play sessions help indoor cats stay active and mentally engaged.</p>
            </div>
          </div>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-5">
          <span>How often should I clean the litter box?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="answer-5">
          <div class="answer">
            <div class="answer-inner">
              <p>Scoop the litter box at least once daily and replace the litter regularly. A clean box supports healthy habits and reduces odors in your home.</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  </main>

  <script>
    const questions = document.querySelectorAll(".question");

    questions.forEach((question) => {
      question.addEventListener("click", () => {
        const example = question.closest(".example");
        const isOpen = question.getAttribute("aria-expanded") === "true";

        question.setAttribute("aria-expanded", String(!isOpen));
        example.classList.toggle("is-open", !isOpen);
      });
    });
  </script>
</body>
</html>
